import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';
import { randomUUID } from 'node:crypto';

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

/** A row of the `jobs` table, exactly as stored. Converted to the public shape in jobs.ts. */
export interface JobRow {
  seq: number;
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  completed: number;
  output: string | null;
  error: string | null;
  created_at: string;
  updated_at: string;
  idempotency_key: string | null;
  /** Epoch milliseconds before which a queued job must not be claimed (retry deadline). */
  available_at: number;
}

/** Normalized submission after defaults are applied. */
export interface Payload {
  input: string;
  steps: number;
  failAttempts: number;
}

export type SubmitResult = { kind: 'created' | 'replayed'; row: JobRow } | { kind: 'conflict' };

const SCHEMA = `
CREATE TABLE IF NOT EXISTS jobs (
  seq INTEGER PRIMARY KEY AUTOINCREMENT,
  id TEXT NOT NULL UNIQUE,
  status TEXT NOT NULL CHECK (status IN ('queued', 'running', 'completed', 'failed')),
  input TEXT NOT NULL,
  steps INTEGER NOT NULL,
  fail_attempts INTEGER NOT NULL,
  attempts INTEGER NOT NULL DEFAULT 0,
  completed INTEGER NOT NULL DEFAULT 0,
  output TEXT,
  error TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  idempotency_key TEXT UNIQUE,
  available_at INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS jobs_pickup ON jobs (status, available_at, seq);
CREATE TABLE IF NOT EXISTS worker_heartbeat (
  id INTEGER PRIMARY KEY CHECK (id = 1),
  at INTEGER NOT NULL
);
`;

/** Opens the SQLite database shared by the server and worker processes, and ensures the schema exists. */
export function openDatabase(path: string = process.env.DATABASE_PATH ?? 'data/jobs.db'): DatabaseSync {
  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  // busy_timeout first: switching to WAL takes a brief exclusive lock, and the server and worker
  // open the same database at once, so the loser must wait rather than fail.
  db.exec('PRAGMA busy_timeout = 5000; PRAGMA journal_mode = WAL;');
  // Both processes run this; IF NOT EXISTS plus an immediate transaction makes it safe in either order.
  withTransaction(db, () => db.exec(SCHEMA));
  return db;
}

/** Runs `fn` in a short BEGIN IMMEDIATE transaction. Never await inside `fn`. */
export function withTransaction<T>(db: DatabaseSync, fn: () => T): T {
  db.exec('BEGIN IMMEDIATE');
  try {
    const result = fn();
    db.exec('COMMIT');
    return result;
  } catch (err) {
    try {
      db.exec('ROLLBACK');
    } catch {
      // no transaction was active
    }
    throw err;
  }
}

type Param = string | number | null;

function get<T>(db: DatabaseSync, sql: string, ...params: Param[]): T | undefined {
  return db.prepare(sql).get(...params) as unknown as T | undefined;
}

function all<T>(db: DatabaseSync, sql: string, ...params: Param[]): T[] {
  return db.prepare(sql).all(...params) as unknown as T[];
}

function run(db: DatabaseSync, sql: string, ...params: Param[]): void {
  db.prepare(sql).run(...params);
}

/**
 * Creates a job, or replays/conflicts with an existing job that used the same idempotency key.
 * The lookup and insert share one immediate transaction, so concurrent requests cannot both insert.
 */
export function submitJob(db: DatabaseSync, payload: Payload, key: string | null): SubmitResult {
  return withTransaction<SubmitResult>(db, () => {
    if (key !== null) {
      const existing = get<JobRow>(db, 'SELECT * FROM jobs WHERE idempotency_key = ?', key);
      if (existing) {
        const same =
          existing.input === payload.input &&
          existing.steps === payload.steps &&
          existing.fail_attempts === payload.failAttempts;
        return same ? { kind: 'replayed', row: existing } : { kind: 'conflict' };
      }
    }
    const now = new Date().toISOString();
    run(
      db,
      `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, completed, output, error,
                         created_at, updated_at, idempotency_key, available_at)
       VALUES (?, 'queued', ?, ?, ?, 0, 0, NULL, NULL, ?, ?, ?, 0)`,
      randomUUID(),
      payload.input,
      payload.steps,
      payload.failAttempts,
      now,
      now,
      key,
    );
    const id = get<{ id: string }>(db, 'SELECT id FROM jobs WHERE rowid = last_insert_rowid()')!.id;
    return { kind: 'created', row: get<JobRow>(db, 'SELECT * FROM jobs WHERE id = ?', id)! };
  });
}

export function getJobById(db: DatabaseSync, id: string): JobRow | undefined {
  return get<JobRow>(db, 'SELECT * FROM jobs WHERE id = ?', id);
}

/** All jobs, newest first (by insertion sequence). */
export function listJobs(db: DatabaseSync): JobRow[] {
  return all<JobRow>(db, 'SELECT * FROM jobs ORDER BY seq DESC');
}

/**
 * Claims the next unit of work in one immediate transaction.
 * A job left `running` (interrupted worker) is resumed first without changing its attempt number.
 * Otherwise the oldest eligible queued job starts a new attempt.
 */
export function claimNextJob(db: DatabaseSync, now: number): JobRow | undefined {
  return withTransaction<JobRow | undefined>(db, () => {
    const ts = new Date(now).toISOString();
    const interrupted = get<JobRow>(db, "SELECT * FROM jobs WHERE status = 'running' ORDER BY seq LIMIT 1");
    if (interrupted) {
      run(db, 'UPDATE jobs SET completed = 0, output = NULL, error = NULL, updated_at = ? WHERE seq = ?', ts, interrupted.seq);
      return get<JobRow>(db, 'SELECT * FROM jobs WHERE seq = ?', interrupted.seq);
    }
    const next = get<JobRow>(
      db,
      "SELECT * FROM jobs WHERE status = 'queued' AND available_at <= ? ORDER BY seq LIMIT 1",
      now,
    );
    if (!next) return undefined;
    run(
      db,
      `UPDATE jobs SET status = 'running', attempts = attempts + 1, completed = 0,
                       output = NULL, error = NULL, updated_at = ? WHERE seq = ?`,
      ts,
      next.seq,
    );
    return get<JobRow>(db, 'SELECT * FROM jobs WHERE seq = ?', next.seq);
  });
}

export function setProgress(db: DatabaseSync, id: string, completed: number, now: number): void {
  run(db, 'UPDATE jobs SET completed = ?, updated_at = ? WHERE id = ?', completed, new Date(now).toISOString(), id);
}

export function completeJob(db: DatabaseSync, id: string, output: string, now: number): void {
  run(
    db,
    `UPDATE jobs SET status = 'completed', completed = steps, output = ?, error = NULL, updated_at = ?
     WHERE id = ?`,
    output,
    new Date(now).toISOString(),
    id,
  );
}

/** Returns a failed attempt to the queue; it may not be claimed again before `availableAt`. */
export function scheduleRetry(db: DatabaseSync, id: string, availableAt: number, now: number): void {
  run(
    db,
    `UPDATE jobs SET status = 'queued', completed = 0, output = NULL, error = NULL,
                     available_at = ?, updated_at = ? WHERE id = ?`,
    availableAt,
    new Date(now).toISOString(),
    id,
  );
}

export function failJob(db: DatabaseSync, id: string, attempts: number, now: number): void {
  run(
    db,
    `UPDATE jobs SET status = 'failed', completed = 0, output = NULL, error = 'transient failure',
                     attempts = ?, updated_at = ? WHERE id = ?`,
    attempts,
    new Date(now).toISOString(),
    id,
  );
}

export function writeHeartbeat(db: DatabaseSync, now: number): void {
  run(
    db,
    'INSERT INTO worker_heartbeat (id, at) VALUES (1, ?) ON CONFLICT (id) DO UPDATE SET at = excluded.at',
    now,
  );
}

export function clearHeartbeat(db: DatabaseSync): void {
  run(db, 'DELETE FROM worker_heartbeat WHERE id = 1');
}

/** Epoch milliseconds of the worker's last heartbeat, if any. */
export function readHeartbeat(db: DatabaseSync): number | undefined {
  return get<{ at: number }>(db, 'SELECT at FROM worker_heartbeat WHERE id = 1')?.at;
}

