}

export function completeJob(db: DatabaseSync, id: string, output: string, now: number): void {
  run(
    db,
    `UPDATE jobs SET status = 'completed', completed = steps, output = ?, error = NULL, updated_at = ?
     WHERE id = ?`,
    output,
    new Date(now).toISOString(),
    id,
  );
