import type { JobRow, JobStatus, Payload } from './db.ts';

export interface FieldError {
  field: string;
  message: string;
}

/** The public job shape returned by every endpoint that returns a job. */
export interface PublicJob {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

export type SubmissionOutcome =
  | { ok: true; payload: Payload; key: string | null }
  | { ok: false; fields: FieldError[] };

export const IDEMPOTENCY_KEY_PATTERN = /^[A-Za-z0-9_-]{1,128}$/;

const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);
const DEFAULT_STEPS = 5;
const DEFAULT_FAIL_ATTEMPTS = 0;

function isIntegerInRange(value: unknown, min: number, max: number): value is number {
  return typeof value === 'number' && Number.isInteger(value) && value >= min && value <= max;
}

/**
 * Validates a submission. `body` is the raw UTF-8 text, or `null` when it exceeded the size limit.
 * Every applicable field error is collected rather than stopping at the first.
 */
export function validateSubmission(request: {
  contentType: string | undefined;
  body: string | null;
  idempotencyKey: string | string[] | undefined;
}): SubmissionOutcome {
  const fields: FieldError[] = [];

  let key: string | null = null;
  const header = request.idempotencyKey;
  if (header !== undefined) {
    if (Array.isArray(header) || !IDEMPOTENCY_KEY_PATTERN.test(header)) {
      fields.push({ field: 'Idempotency-Key', message: 'must be 1 to 128 characters of letters, digits, "_" or "-"' });
    } else {
      key = header;
    }
  }

  const mediaType = request.contentType?.split(';')[0]?.trim().toLowerCase();
  if (mediaType !== 'application/json') {
    fields.push({ field: 'body', message: 'Content-Type must be application/json' });
    return { ok: false, fields };
  }
  if (request.body === null) {
    fields.push({ field: 'body', message: 'body is too large' });
    return { ok: false, fields };
  }

  let parsed: unknown;
  try {
    parsed = JSON.parse(request.body);
  } catch {
    fields.push({ field: 'body', message: 'body must be valid JSON' });
    return { ok: false, fields };
  }
  if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
    fields.push({ field: 'body', message: 'body must be a JSON object' });
    return { ok: false, fields };
  }

  const obj = parsed as Record<string, unknown>;
  for (const name of Object.keys(obj)) {
    if (!ALLOWED_FIELDS.has(name)) fields.push({ field: name, message: 'is not a recognized field' });
  }

  let input = '';
  if (!Object.hasOwn(obj, 'input')) {
    fields.push({ field: 'input', message: 'is required' });
  } else if (typeof obj.input !== 'string') {
    fields.push({ field: 'input', message: 'must be a string' });
  } else if (obj.input.length < 1 || obj.input.length > 1000) {
    fields.push({ field: 'input', message: 'must be 1 to 1000 characters' });
  } else if (obj.input.trim() === '') {
    fields.push({ field: 'input', message: 'must not be blank' });
  } else {
    input = obj.input;
  }

  const steps = Object.hasOwn(obj, 'steps') ? obj.steps : DEFAULT_STEPS;
  if (!isIntegerInRange(steps, 1, 20)) fields.push({ field: 'steps', message: 'must be an integer from 1 to 20' });

  const failAttempts = Object.hasOwn(obj, 'failAttempts') ? obj.failAttempts : DEFAULT_FAIL_ATTEMPTS;
  if (!isIntegerInRange(failAttempts, 0, 5)) {
    fields.push({ field: 'failAttempts', message: 'must be an integer from 0 to 5' });
  }

  if (fields.length > 0 || typeof steps !== 'number' || typeof failAttempts !== 'number') {
    return { ok: false, fields };
  }
  return { ok: true, payload: { input, steps, failAttempts }, key };
}

/** Converts a stored row to the public job shape. Internal columns are not exposed. */
export function toPublicJob(row: JobRow): PublicJob {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.completed, total: row.steps },
    result: row.status === 'completed' ? { output: row.output ?? '' } : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

