import { readFileSync } from 'node:fs';
import { getJobById, listJobs, openDatabase, readHeartbeat, submitJob } from './db.ts';
import { toPublicJob, validateSubmission, type FieldError } from './jobs.ts';

const HEARTBEAT_FRESH_MS = 3_000;
const MAX_BODY_BYTES = 64 * 1024;
const SHUTDOWN_GRACE_MS = 3_000;

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

function sendJson(res: ServerResponse, status: number, body: unknown, extraHeaders: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...extraHeaders });
  res.end(JSON.stringify(body));
}

function sendError(
  res: ServerResponse,
  status: number,
  code: string,
  message: string,
  fields?: FieldError[],
  extraHeaders: Record<string, string> = {},
): void {
  const error: { code: string; message: string; fields?: FieldError[] } = { code, message };
  if (fields) error.fields = fields;
  sendJson(res, status, { error }, extraHeaders);
}

/** Reads the request body as UTF-8. Resolves to `null` when it exceeds the size limit. */
function readBody(req: IncomingMessage): Promise<string | null> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve(tooLarge ? null : Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
    req.on('close', () => {
      if (!req.complete) reject(new Error('request closed before the body was received'));
    });
  });
}

function methodNotAllowed(res: ServerResponse, allow: string): void {
  sendError(res, 405, 'method_not_allowed', 'Method not allowed for this path.', undefined, { allow });
}

const JOB_ID_PATH = /^\/api\/jobs\/([^/]+)$/;

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const url = new URL(req.url ?? '/', 'http://localhost');
  const path = url.pathname;
  const method = req.method ?? 'GET';
  const isRead = method === 'GET' || method === 'HEAD';

  if (path === '/') {
    if (!isRead) return methodNotAllowed(res, 'GET, HEAD');
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(method === 'HEAD' ? undefined : uiHtml);
    return;
  }

  if (path === '/health') {
    if (!isRead) return methodNotAllowed(res, 'GET, HEAD');
    const heartbeat = readHeartbeat(db);
    const up = heartbeat !== undefined && Date.now() - heartbeat <= HEARTBEAT_FRESH_MS;
    sendJson(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
    return;
  }

  if (path === '/api/jobs') {
    if (isRead) {
      sendJson(res, 200, { jobs: listJobs(db).map(toPublicJob) });
      return;
    }
    if (method !== 'POST') return methodNotAllowed(res, 'GET, HEAD, POST');
    const outcome = validateSubmission({
      contentType: req.headers['content-type'],
      body: await readBody(req),
      idempotencyKey: req.headers['idempotency-key'],
    });
    if (!outcome.ok) {
      sendError(res, 400, 'invalid_request', 'The submission is invalid.', outcome.fields);
      return;
    }
    const result = submitJob(db, outcome.payload, outcome.key);
    if (result.kind === 'conflict') {
      sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
      return;
    }
    sendJson(res, result.kind === 'created' ? 201 : 200, toPublicJob(result.row));
    return;
  }

  const match = JOB_ID_PATH.exec(path);
  if (match) {
    if (!isRead) return methodNotAllowed(res, 'GET, HEAD');
    const row = getJobById(db, decodeURIComponent(match[1]!));
    if (!row) {
      sendError(res, 404, 'not_found', 'No job with that id.');
      return;
    }
    sendJson(res, 200, toPublicJob(row));
    return;
  }

  sendError(res, 404, 'not_found', 'No such route.');
}

const server = createServer((req, res) => {
  handle(req, res).catch((err: unknown) => {
    console.error('request failed:', err);
    if (res.headersSent) {
      res.end();
    } else {
      sendError(res, 500, 'internal_error', 'An unexpected error occurred.');
    }
  });
});

const port = Number(process.env.PORT ?? 3000);
server.listen(port, () => console.log(`server listening on ${port}`));

let shuttingDown = false;

function shutdown(signal: NodeJS.Signals): void {
  if (shuttingDown) return;
  shuttingDown = true;
  console.log(`${signal} received, shutting down`);
  // Stop accepting connections, let in-flight requests finish, and close the rest after a grace period.
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeIdleConnections();
  setTimeout(() => server.closeAllConnections(), SHUTDOWN_GRACE_MS).unref();
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

