import { setTimeout as sleep } from 'node:timers/promises';
import {
  claimNextJob,
  clearHeartbeat,
  completeJob,
  failJob,
  openDatabase,
  scheduleRetry,
  setProgress,
  writeHeartbeat,
  type JobRow,
} from './db.ts';

const STEP_MS = 100;
const IDLE_MS = 100;
const HEARTBEAT_MS = 500;
const RETRY_DELAY_MS = 500;
const MAX_ATTEMPTS = 3;

const db = openDatabase();
let stopping = false;

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

function heartbeat(): void {
  try {
    writeHeartbeat(db, Date.now());
  } catch (err) {
    console.error('heartbeat failed:', err);
  }
}

heartbeat();
const heartbeatTimer = setInterval(heartbeat, HEARTBEAT_MS);

/**
 * Runs one attempt of a job. Returns early without writing terminal state if the worker is
 * stopping; the job then stays `running` and is resumed by the next worker.
 */
async function processAttempt(job: JobRow): Promise<void> {
  const attempt = job.attempts;
  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) return;

    if (step === 1 && attempt <= job.fail_attempts) {
      const now = Date.now();
      if (attempt < MAX_ATTEMPTS) {
        scheduleRetry(db, job.id, now + RETRY_DELAY_MS, now);
      } else {
        failJob(db, job.id, attempt, now);
      }
      return;
    }

    if (step < job.steps) {
      setProgress(db, job.id, step, Date.now());
    } else {
      completeJob(db, job.id, job.input.toUpperCase(), Date.now());
    }
  }
}

async function run(): Promise<void> {
  while (!stopping) {
    let job: JobRow | undefined;
    try {
      job = claimNextJob(db, Date.now());
    } catch (err) {
      console.error('claim failed:', err);
      await sleep(IDLE_MS);
      continue;
    }
    if (!job) {
      await sleep(IDLE_MS);
      continue;
    }
    try {
      await processAttempt(job);
    } catch (err) {
      // The job stays `running` and is resumed on the next claim.
      console.error('processing failed:', err);
      await sleep(IDLE_MS);
    }
  }
}

console.log('worker started');
await run();

clearInterval(heartbeatTimer);
try {
  clearHeartbeat(db);
} catch (err) {
  console.error('clearing heartbeat failed:', err);
}
db.close();
console.log('worker stopped');

